vec4 windowCellProfile( float q ) {
  float family = floor( q / 16384.0 );
  float owner = mod( mod( q, 16384.0 ) * 251.0 + 97.0, 16384.0 );
  float widthChoice = mod( owner, 5.0 );
  float heightChoice = mod( floor( owner / 5.0 ), 5.0 );
  float paneChoice = mod( floor( owner / 25.0 ), 5.0 );
  vec4 cell = vec4( 0.0 );
  if ( family < 0.5 ) {
    cell.x = ( 36.0 + 2.0 * widthChoice ) / 8.0;
    cell.y = ( 30.0 + 2.0 * heightChoice ) / 8.0;
    cell.z = ( 368.0 + 8.0 * paneChoice ) / 1024.0;
  }
  else if ( family < 1.5 ) {
    cell.x = ( 72.0 + 5.0 * widthChoice ) / 8.0;
    cell.y = ( 36.0 + 2.0 * heightChoice ) / 8.0;
    cell.z = ( 450.0 + 8.0 * paneChoice ) / 1024.0;
  }
  else if ( family < 2.5 ) {
    cell.x = ( 36.0 + 2.0 * widthChoice ) / 8.0;
    cell.y = ( 56.0 + 4.0 * heightChoice ) / 8.0;
    cell.z = ( 320.0 + 8.0 * paneChoice ) / 1024.0;
  }
  else if ( family < 3.5 ) {
    cell.x = ( 52.0 + 3.0 * widthChoice ) / 8.0;
    cell.y = ( 40.0 + 2.0 * heightChoice ) / 8.0;
    cell.z = ( 404.0 + 8.0 * paneChoice ) / 1024.0;
  }
  cell.w = 0.11890000104904175 / cell.z;
  return cell;
}


